import{_ as a,o as t,c as e,a4 as n}from"./chunks/framework.B0hSrcZ6.js";const r="/info/22-feishu-wechat.webp",l="/info/22-feishu-wechat-s1.webp",i="/info/22-feishu-wechat-s2.webp",s="/info/22-feishu-wechat-s3.webp",f=JSON.parse('{"title":"第 22 章 接入飞书与微信","description":"本章介绍无需公网服务器将 Grok Bot 接入飞书与微信的方案。对比各通道技术选型，指导读者配置消息过滤规则与素材入库，避免群聊闲聊快速耗尽整周额度。","frontmatter":{},"headers":[],"relativePath":"part3/22-feishu-wechat.md","filePath":"part3/22-feishu-wechat.md","lastUpdated":1792210948000}'),h={name:"part3/22-feishu-wechat.md"};function c(d,o,g,p,b,u){return t(),e("div",null,[...o[0]||(o[0]=[n('<h1 id="第-22-章-接入飞书与微信" tabindex="-1">第 22 章 接入飞书与微信 <a class="header-anchor" href="#第-22-章-接入飞书与微信" aria-label="Permalink to &quot;第 22 章 接入飞书与微信&quot;">​</a></h1><p>不用公网 IP 和自建服务器，就能把 Grok Bot 安全接入飞书与微信。</p><p>The X Subscription（2026年10月12日生效）按周扣额度，<strong>群聊必须配消息过滤</strong>，否则闲聊会耗光整周额度。</p><ul><li><strong>飞书多 Bot 协同</strong>：走官方 Python SDK 长连接与「飞书应用管家」模板。</li><li><strong>微信 ClawBot 直连</strong>：靠官方「微信ClawBot」插件和 iLink 接口。</li><li><strong>微信快捷指令收录</strong>：借苹果快捷指令与 Webhook 归档记录。</li></ul><p><img src="'+r+'" alt="接入飞书与微信" width="1600" height="1013" decoding="async"></p><h2 id="接入通道对比与技术选型" tabindex="-1">接入通道对比与技术选型 <a class="header-anchor" href="#接入通道对比与技术选型" aria-label="Permalink to &quot;接入通道对比与技术选型&quot;">​</a></h2><p><img src="'+l+'" alt="接入通道对比与技术选型" width="1600" height="1013" loading="lazy" decoding="async"></p><p><strong>三种接入方式全都不需要公网 IP</strong>。</p><ul><li>飞书多 Bot 通道：用于团队办公与群聊派工。走官方 WebSocket 长连接出站，支持富文本与卡片，群内仅响应 @ 保护额度。</li><li>微信 ClawBot 通道：用于个人日常随身助理与调度。走 iLink 长轮询，仅支持纯文本，靠白名单单聊避免无效唤醒。</li><li>微信快捷指令通道：用于图文与音频资产入库。走 Webhook 单向推送并返回回执，按需触发，无消息不产生额外消耗。</li></ul><h2 id="团队接入飞书-多-bot-协同与飞书应用管家" tabindex="-1">团队接入飞书：多 Bot 协同与飞书应用管家 <a class="header-anchor" href="#团队接入飞书-多-bot-协同与飞书应用管家" aria-label="Permalink to &quot;团队接入飞书：多 Bot 协同与飞书应用管家&quot;">​</a></h2><p><img src="'+i+'" alt="团队接入飞书：多 Bot 协同与飞书应用管家" width="1600" height="1013" loading="lazy" decoding="async"></p><h3 id="飞书长连接与门铃触发器机制" tabindex="-1">飞书长连接与门铃触发器机制 <a class="header-anchor" href="#飞书长连接与门铃触发器机制" aria-label="Permalink to &quot;飞书长连接与门铃触发器机制&quot;">​</a></h3><p>走长连接出站，<strong>免去公网 IP、证书和开放端口</strong>。</p><ol><li>飞书自建应用：负责群聊与单聊收发。</li><li>云端转发程序：后台监听长连接并转交。</li><li>门铃触发器：唤醒 Bot 并调 SDK 回复。</li></ol><p>怕重复配置，用「飞书应用管家」<strong>扫码自动建应用</strong>。</p><h3 id="怎么做-从单-bot-跑通到多-bot-协同" tabindex="-1">怎么做：从单 Bot 跑通到多 Bot 协同 <a class="header-anchor" href="#怎么做-从单-bot-跑通到多-bot-协同" aria-label="Permalink to &quot;怎么做：从单 Bot 跑通到多 Bot 协同&quot;">​</a></h3><h4 id="扫码建首个-bot-文章主编" tabindex="-1">扫码建首个 Bot（文章主编） <a class="header-anchor" href="#扫码建首个-bot-文章主编" aria-label="Permalink to &quot;扫码建首个 Bot（文章主编）&quot;">​</a></h4><ol><li>私聊让 Bot 调飞书 SDK 扫码建应用。<strong>该链接为一次性凭证且仅限管理员使用，切勿点他人链接或转发。</strong></li><li>浏览器打开链接点「创建」并确认权限，凭证自动回传。</li><li>收到飞书测试消息后回复一条，<strong>Bot 自动将你的 Open ID 写入白名单</strong>。</li></ol><h4 id="创建门铃例程" tabindex="-1">创建门铃例程 <a class="header-anchor" href="#创建门铃例程" aria-label="Permalink to &quot;创建门铃例程&quot;">​</a></h4><ol><li>点击 Bot 名称进 [help_grok-bot_routines.md](file:///workspace/grok-bot-learn/v3/src/help_grok-bot_routines.md) 的 <strong>Details</strong> 面板。</li><li>在例程建 Webhook 门铃，获取 POST to 地址与 key。</li><li><strong>必须在 Bot 弹出的加密输入框提交凭证</strong>，避免明文泄露。单聊发测试文本，Bot 正常回复即跑通。</li></ol><h4 id="批量建应用与群聊协同" tabindex="-1">批量建应用与群聊协同 <a class="header-anchor" href="#批量建应用与群聊协同" aria-label="Permalink to &quot;批量建应用与群聊协同&quot;">​</a></h4><ol><li>导入模板 <code>https://x.ai/bot/AJpUlCwa8tyMX7L5UHnuY</code>。登记表与恢复脚本存 Git 私有仓库，不存明文密钥。</li><li>向管家下令批量生成扫码链接（<strong>每链接 1 小时有效</strong>），扫码并在加密窗填 key，管家自动拉起转发。</li><li>建群拉入各 Bot，<strong>发 <code>@所有人</code> 确认汇报管辖范围</strong>；<code>@文章主编</code> 调 <code>虚拟机服务管家</code>，服务管家发登记表进群即完成协同。</li></ol><h4 id="交互安全" tabindex="-1">交互安全 <a class="header-anchor" href="#交互安全" aria-label="Permalink to &quot;交互安全&quot;">​</a></h4><ul><li><strong>指令来源校验</strong>：仅响应群内白名单管理员的直接指令。</li><li><strong>飞书卡片确认</strong>：改配置、写库或重启等高危操作推送带「同意」与「驳回」按钮的卡片，<strong>在飞书内点击即可二次授权</strong>。</li></ul><h3 id="做到什么程度算好" tabindex="-1">做到什么程度算好 <a class="header-anchor" href="#做到什么程度算好" aria-label="Permalink to &quot;做到什么程度算好&quot;">​</a></h3><ul><li><strong>端到端耗时低于 1 秒</strong>：发消息基本秒回。</li><li><strong>群聊消息精准分流</strong>：闲聊静默，单独 @ 谁谁回，@所有人按职责汇报不抢答。</li><li><strong>高可用自愈</strong>：退出 5 秒内拉起，每 5 分钟巡检假死，强杀进程约 9 秒恢复。</li></ul><p>实操参考<a href="https://jcng5q8n0f3z.feishu.cn/wiki/F2VXw4hVbirRUjk5QgFcWS0jnJg" target="_blank" rel="noreferrer">《Grok Bot 团队接入飞书保姆级教程（附飞书管家模板）》</a>。</p><h2 id="个人接入微信-微信-clawbot-插件直连" tabindex="-1">个人接入微信：微信 ClawBot 插件直连 <a class="header-anchor" href="#个人接入微信-微信-clawbot-插件直连" aria-label="Permalink to &quot;个人接入微信：微信 ClawBot 插件直连&quot;">​</a></h2><p><img src="'+s+`" alt="个人接入微信：微信 ClawBot 插件直连" width="1600" height="1013" loading="lazy" decoding="async"></p><p>走官方 iLink 接口（<code>ilinkai.weixin.qq.com</code>），纯出站长轮询，<strong>不开放公网端口，合规且无封号风险</strong>。</p><h3 id="三步完成接入" tabindex="-1">三步完成接入 <a class="header-anchor" href="#三步完成接入" aria-label="Permalink to &quot;三步完成接入&quot;">​</a></h3><ol><li><strong>发送提示词</strong>：电脑端向主 Bot 发送下方指令，等待自动生成通信组件。</li></ol><details class="details custom-block"><summary>三步完成接入</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我想把你接到我的微信上，让我能在微信里直接给你发消息、收到你的回复。请按下面的思路做，每做完一步告诉我结果，需要我操作的地方停下来等我。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1、先调研方案：腾讯「微信ClawBot」插件用的是 iLink 接口（ilinkai.weixin.qq.com）。请确认怎么用 getupdates 长轮询收消息、怎么用 sendmessage 回消息。整个程序只走出站请求，不要开公网端口。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2、在 Grok Bot 里建一个由 webhook 触发的 routine，名字可以叫「微信下旨入口」。建好后告诉我去 routine 面板复制 Webhook URL 和 key，然后弹出加密弹框让我填进去，不要让我在聊天里发明文。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3、在你的云端电脑上写一个小转发程序：收到微信消息后 POST 给这个 routine；你处理完以后，用一个 reply 脚本把回复发回微信，同时在我们的主聊天里同步一份。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4、等我在手机微信里启用 ClawBot 插件以后，生成二维码让我用手机扫码确认，同时给我一个可以在微信里直接打开的备用链接。二维码大约 5 分钟有效。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>5、绑定成功后，提醒我先在 ClawBot 对话里发一句话，因为回复要用到这条消息带的 context_token。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>6、规则：只认绑定的这一个人，别人的消息不处理；回复一律用纯文本，不要用 Markdown，因为微信不渲染 Markdown。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>7、最后告诉我：云端电脑重启以后，怎么把转发程序重新拉起来；如果遇到错误码 -14（凭证过期），提醒我重新扫码。</span></span></code></pre></div></details><ol start="2"><li><strong>配置密钥</strong>：打开主 Bot 的「微信下旨入口」例程，复制 Webhook 的 <strong>POST to</strong> 和 <strong>key</strong> 提交到加密框。</li><li><strong>绑定与激活</strong>： <ul><li>微信版本须满足 <strong>iOS ≥ 8.0.70，Android ≥ 8.0.69</strong>，在「设置-插件」启用「微信ClawBot」。</li><li>对电脑 Bot 发「插件开好了」，微信扫码授权（二维码 5 分钟内有效）。</li><li><strong>必须主动向微信 ClawBot 发首条消息</strong>（如“你好”），获取 <code>context_token</code> 激活回包。</li></ul></li></ol><h3 id="验收标准" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准" aria-label="Permalink to &quot;验收标准&quot;">​</a></h3><ul><li><strong>双向同步</strong>：微信端秒级回复，电脑端实时存档。</li><li><strong>子 Agent 调度</strong>：在微信直接派发推特检索、视频转录任务。</li><li><strong>安全隔离</strong>：未绑定的微信号无法唤醒。</li></ul><p>细节见<a href="https://jcng5q8n0f3z.feishu.cn/wiki/LehUwOhxAijkigkkVlDclVVunQg" target="_blank" rel="noreferrer">《如何把 Grok Bot 接入你的微信？保姆级新手指南来了（附详细提示词）｜Kin》</a>。</p><h2 id="微信内容入库-快捷指令打通聊天记录与多媒体" tabindex="-1">微信内容入库：快捷指令打通聊天记录与多媒体 <a class="header-anchor" href="#微信内容入库-快捷指令打通聊天记录与多媒体" aria-label="Permalink to &quot;微信内容入库：快捷指令打通聊天记录与多媒体&quot;">​</a></h2><p>通过快捷指令把合并转发的 ZIP 包传给临时网盘，<strong>再推给 Grok Bot 的 Webhook 自动归档</strong>。</p><h3 id="配置与操作" tabindex="-1">配置与操作 <a class="header-anchor" href="#配置与操作" aria-label="Permalink to &quot;配置与操作&quot;">​</a></h3><ol><li>在 Grok Bot 对话窗口发提示词创建例程：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我创建一个 Webhook 触发的例行任务。快捷指令会用 POST 请求发来一个 JSON，里面只有一个字段 info。info 可能是我输入的文字，也可能是一个文件下载链接，比如微信聊天记录压缩包、截图、录音。收到后：如果是链接就先下载文件再读取，压缩包先解压；然后整理出要点，收录进知识库，最后给我一份回执，写清楚收录了什么、存在哪里。</span></span></code></pre></div><p>在详情页 Routine 列表里，<strong>复制 Webhook 的 POST to 地址与 key 密钥</strong>。</p><ol start="2"><li><p>导入快捷指令：<code>https://www.icloud.com/shortcuts/2b77155d7c744110a0f0f9ef1bdc42bf</code>。</p></li><li><p>填入 POST to、key 和图床 ID。<code>filebin.net</code> 文件存 7 天，<strong>ID 须设 8 位以上随机字符</strong>（如 <code>kb7x9q2m</code>）防覆盖泄露；<strong>分享前务必清空这三项</strong>。</p></li><li><p>微信多选聊天记录，合并转发到其他应用，选快捷指令「发送给知识库 Bot」中的「接收转发」。未接收转发时会读剪贴板，也能选「截图」或「录音」直传。</p></li></ol><h3 id="验收标准-1" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准-1" aria-label="Permalink to &quot;验收标准&quot;">​</a></h3><ul><li><strong>多媒体解析完整</strong>：解压并分类图片、文档与语音（如 13 个设计灵感网站按整站、App、组件建索引）。</li><li><strong>回执规范</strong>：标清主题要点、笔记存储路径与原始 ZIP 归档路径。</li></ul><p>参考：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/IwrfwYt1ti0aDWk3YEdcGyQRnUb" target="_blank" rel="noreferrer">《微信聊天记录打通 Grok Bot：快捷指令进阶版》</a>。</p><h2 id="容易踩的坑与排查方案" tabindex="-1">容易踩的坑与排查方案 <a class="header-anchor" href="#容易踩的坑与排查方案" aria-label="Permalink to &quot;容易踩的坑与排查方案&quot;">​</a></h2><h3 id="_1-飞书权限配置不足导致群消息无法接收" tabindex="-1">1. 飞书权限配置不足导致群消息无法接收 <a class="header-anchor" href="#_1-飞书权限配置不足导致群消息无法接收" aria-label="Permalink to &quot;1. 飞书权限配置不足导致群消息无法接收&quot;">​</a></h3><ul><li><strong>坑点</strong>：单聊正常但群内 <code>@</code> 没反应也没日志，因初选 7 项权限，漏了「获取群组中所有 @机器人的消息」。</li><li><strong>解法</strong>：走 SDK 扫码生成补权链接，管理员确认扩到 14 项，<strong>无需重新发版</strong>。</li></ul><h3 id="_2-飞书群聊过滤规则误判与长连接断线重推" tabindex="-1">2. 飞书群聊过滤规则误判与长连接断线重推 <a class="header-anchor" href="#_2-飞书群聊过滤规则误判与长连接断线重推" aria-label="Permalink to &quot;2. 飞书群聊过滤规则误判与长连接断线重推&quot;">​</a></h3><ol><li>漏消息与抢答：飞书 <code>@所有人</code> 不在 mention 数组，不验 ID 又会全员抢答。<strong>脚本必须卡准目标 ID，只响应「<code>@自己</code>」或「<code>@所有人</code>」</strong>。</li><li>重复回复：网络恢复后官方会自动补推，<strong>千万别手动二次补发</strong>。</li></ol><h3 id="_3-跨-bot-调用的信任链与授权卡片缺失" tabindex="-1">3. 跨 Bot 调用的信任链与授权卡片缺失 <a class="header-anchor" href="#_3-跨-bot-调用的信任链与授权卡片缺失" aria-label="Permalink to &quot;3. 跨 Bot 调用的信任链与授权卡片缺失&quot;">​</a></h3><ol><li>群里 Bot 互调没反应，是<strong>跨 Bot 消息默认不可信</strong>，全卡在私聊等确认。</li><li>转发层配白名单认管理员 Open ID；高危操作推<strong>带同意/驳回的飞书卡片</strong>确认。</li></ol><h3 id="_4-虚拟机-python-运行环境路径错误" tabindex="-1">4. 虚拟机 Python 运行环境路径错误 <a class="header-anchor" href="#_4-虚拟机-python-运行环境路径错误" aria-label="Permalink to &quot;4. 虚拟机 Python 运行环境路径错误&quot;">​</a></h3><ul><li>脚本报错提示找不到 <code>lark-oapi</code>，通常是配置守护任务时<strong>误用了系统默认的 <code>/usr/bin/python3</code></strong>。</li><li>在启动脚本、Supervisor 和定时任务里，<strong>必须写死虚拟环境的绝对路径</strong>（如 <code>/home/user/venv/bin/python3</code>），别直接调系统全局环境。</li></ul><h3 id="_5-微信-clawbot-二维码失效与错误码-14" tabindex="-1">5. 微信 ClawBot 二维码失效与错误码 -14 <a class="header-anchor" href="#_5-微信-clawbot-二维码失效与错误码-14" aria-label="Permalink to &quot;5. 微信 ClawBot 二维码失效与错误码 -14&quot;">​</a></h3><ul><li>二维码<strong>只有 5 分钟有效期</strong>，超时会失效，出来后赶紧用手机扫。</li><li>后台报错误码 <strong><code>-14</code></strong> 是凭证过期了，重新生成二维码让管理员再扫一次就行。</li></ul><h3 id="_6-微信消息格式混乱与-markdown-渲染失败" tabindex="-1">6. 微信消息格式混乱与 Markdown 渲染失败 <a class="header-anchor" href="#_6-微信消息格式混乱与-markdown-渲染失败" aria-label="Permalink to &quot;6. 微信消息格式混乱与 Markdown 渲染失败&quot;">​</a></h3><ul><li>微信<strong>不解析 Markdown</strong>，星号、反引号和标题符号都会直接露出来。</li><li>在接入提示词或转发脚本里加过滤，<strong>统一转成带换行的纯文本</strong>再发给微信。</li></ul><h3 id="_7-微信合并转发-zip-缺少未加载的多媒体附件" tabindex="-1">7. 微信合并转发 ZIP 缺少未加载的多媒体附件 <a class="header-anchor" href="#_7-微信合并转发-zip-缺少未加载的多媒体附件" aria-label="Permalink to &quot;7. 微信合并转发 ZIP 缺少未加载的多媒体附件&quot;">​</a></h3><p>微信不存原文件，没点开加载的不会打进压缩包，解压就会丢图片。</p><ol><li>转发前，<strong>逐个点开需要保存的图片和文件</strong>。</li><li>等本地完全加载好，再去打包转发。</li></ol><h3 id="_8-临时网盘的命名冲突与隐私泄露风险" tabindex="-1">8. 临时网盘的命名冲突与隐私泄露风险 <a class="header-anchor" href="#_8-临时网盘的命名冲突与隐私泄露风险" aria-label="Permalink to &quot;8. 临时网盘的命名冲突与隐私泄露风险&quot;">​</a></h3><p><code>filebin.net</code> 没账号体系，ID 太简单会撞车，导致报错或下到别人的文件。用的时候注意：</p><ul><li>图床 ID <strong>必须设为 8 位以上随机字符串</strong>。</li><li>别传密码、身份证等隐私内容。</li><li>分享快捷指令前，<strong>删掉自己的专属 ID 与 Webhook 密钥</strong>。</li></ul><h3 id="_9-the-x-subscription-统一订阅下的额度防耗控制" tabindex="-1">9. The X Subscription 统一订阅下的额度防耗控制 <a class="header-anchor" href="#_9-the-x-subscription-统一订阅下的额度防耗控制" aria-label="Permalink to &quot;9. The X Subscription 统一订阅下的额度防耗控制&quot;">​</a></h3><p>群员闲聊会触发例程空转，<strong>一到两天就会耗尽周额度导致 Bot 停止响应</strong>。</p><p>2026 年 10 月 12 日起 The X Subscription 按周从共享池扣额度。</p><p>Plus 档（$8/月）没有 Grok Bot，只有 Premium（$30/月，4x 额度）、Super（$100/月，15x 额度）与 Ultra（$200/月，50x 额度）包含。</p><p>防耗抓两点：</p><ol><li><strong>仅在精准提及（<code>@自己</code>）或特定管理员指令时触发 Webhook</strong>。</li><li>严禁全群无差别监听，避免配置高频短周期轮询。</li></ol><p>详细规则参考 [help_grok-bot_plans.md](file:///workspace/grok-bot-learn/v3/src/help_grok-bot_plans.md) 与 [help_grok-bot_routines.md](file:///workspace/grok-bot-learn/v3/src/help_grok-bot_routines.md)。</p><h2 id="实战案例复盘" tabindex="-1">实战案例复盘 <a class="header-anchor" href="#实战案例复盘" aria-label="Permalink to &quot;实战案例复盘&quot;">​</a></h2><h3 id="飞书多-bot-协同-铁柱agi" tabindex="-1">飞书多 Bot 协同（铁柱AGI） <a class="header-anchor" href="#飞书多-bot-协同-铁柱agi" aria-label="Permalink to &quot;飞书多 Bot 协同（铁柱AGI）&quot;">​</a></h3><p>没公网 IP 也能跑协同，<strong>核心是用出站长连接免打洞</strong>。</p><ol><li><strong>批量注册</strong>：飞书 Python SDK 扫码授权，管家 Bot 读 Git 备份表，托管主编、记账与虚拟机 3 个 Bot 的密钥和 Webhook。</li><li><strong>安全确认</strong>：群内仅响应 <code>@自己</code> 或 <code>@所有人</code>。<strong>高敏感操作由 Bot 推卡片按钮人工授权</strong>。</li></ol><h3 id="微信-clawbot-随身台-kin" tabindex="-1">微信 ClawBot 随身台（Kin） <a class="header-anchor" href="#微信-clawbot-随身台-kin" aria-label="Permalink to &quot;微信 ClawBot 随身台（Kin）&quot;">​</a></h3><p>微信内调度推特运营与文案提取 Bot，<strong>走官方插件长轮询能防封号</strong>。</p><ol><li>给 7×24 小时云电脑发提示词，调腾讯 iLink（<code>ilinkai.weixin.qq.com</code>）跑通 <code>getupdates</code> 轮询与 <code>sendmessage</code> 脚本。</li><li>弹窗交接 Webhook 和密钥，扫码发首条消息拿到初始 <code>context_token</code>。</li><li><strong>踩坑点</strong>：<strong>微信回复必须强制转纯文本</strong>，剥除 Markdown 符号。</li></ol><h3 id="微信图文归库流水线" tabindex="-1">微信图文归库流水线 <a class="header-anchor" href="#微信图文归库流水线" aria-label="Permalink to &quot;微信图文归库流水线&quot;">​</a></h3><p>微信沙盒禁了整包直传，<strong>用临时网盘当中转可绕过限制</strong>。</p><ol><li><strong>中转上传</strong>：Mac 或 iPhone 用「合并转发」导出聊天 ZIP 包，快捷指令自动传到 <code>filebin.net</code>。</li><li><strong>自动归档</strong>：快捷指令拼 JSON 发给 Grok Bot 的 Webhook，解压归档「13 个设计灵感网站」等图文。</li><li><strong>验收标准</strong>：<strong>必须输出带路径与摘要的结构化回执</strong>。</li></ol><h2 id="做完怎么验收" tabindex="-1">做完怎么验收 <a class="header-anchor" href="#做完怎么验收" aria-label="Permalink to &quot;做完怎么验收&quot;">​</a></h2><h3 id="飞书" tabindex="-1">飞书 <a class="header-anchor" href="#飞书" aria-label="Permalink to &quot;飞书&quot;">​</a></h3><ol><li><strong>消息响应</strong>：私聊 1 秒内回复；群聊发普通文字静默，单独 <code>@文章主编</code> 响应，<code>@所有人</code> 各 Bot 依次汇报。</li><li><strong>权限与自愈</strong>：后台开齐 14 项事件权限并支持卡片授权；手动杀掉进程，5 至 10 秒内自动拉起。</li></ol><h3 id="微信" tabindex="-1">微信 <a class="header-anchor" href="#微信" aria-label="Permalink to &quot;微信&quot;">​</a></h3><ol><li><strong>环境与握手</strong>：微信高于 iOS 8.0.70 或 Android 8.0.69 并启用插件；扫码首条用 <code>context_token</code> 回复且无 Markdown 乱码。</li><li><strong>拦截与报错</strong>：未绑定账号直接忽略；重启后自动拉起，<strong>遇到错误码 <code>-14</code> 提示重新扫码</strong>。</li></ol><h3 id="快捷指令" tabindex="-1">快捷指令 <a class="header-anchor" href="#快捷指令" aria-label="Permalink to &quot;快捷指令&quot;">​</a></h3><ol><li><strong>入库操作</strong>：填好 Webhook、Bearer 密钥及 8 位以上图床 ID；微信先点开加载附件再合并转发，也能独立唤醒。</li><li><strong>输出与对账</strong>：<strong>回执须包含提要、笔记路径与留存路径</strong>；在方案页核查用量，避免持续空转扣费。</li></ol><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="https://cursor.com/cn/docs/grok-bot/work" target="_blank" rel="noreferrer">使用 Grok Bot</a>（Grok Bot 官方工作流与技能使用指南）</li><li><a href="https://cursor.com/cn/help/grok-bot/routines" target="_blank" rel="noreferrer">例程使用指南</a>（例程配置、Webhook 调用与计划任务官方文档）</li><li><a href="https://cursor.com/cn/help/grok-bot/plans" target="_blank" rel="noreferrer">方案和计费</a>（The X Subscription 订阅档位与用量说明）</li><li><a href="https://cursor.com/cn/help/grok-bot/secrets" target="_blank" rel="noreferrer">机密信息与密钥管理</a>（安全环境变量与加密弹窗机制）</li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/F2VXw4hVbirRUjk5QgFcWS0jnJg" target="_blank" rel="noreferrer">《Grok Bot 团队接入飞书保姆级教程（附飞书管家模板）》</a>（社区作者 铁柱AGI 原文）</li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/LehUwOhxAijkigkkVlDclVVunQg" target="_blank" rel="noreferrer">《如何把 Grok Bot 接入你的微信？保姆级新手指南来了（附详细提示词）｜Kin》</a>（社区作者 Kin 原文）</li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/IwrfwYt1ti0aDWk3YEdcGyQRnUb" target="_blank" rel="noreferrer">《微信聊天记录打通 Grok Bot：快捷指令进阶版》</a>（社区作者 铁柱AGI 原文）</li></ul>`,92)])])}const m=a(h,[["render",c]]);export{f as __pageData,m as default};
